Other properties can be considered to format and change some behaviors

             public void Initialize()
             {
                 //initialize object...
                 C1FlexGrid c1FlexGrid1 = new C1.Win.FlexGrid.C1FlexGrid(); 

                 //populate data...
                 c1FlexGrid1.DataSource = Enumerable.Range(0, 100).Select(x => new Product()).ToList();

